        var item = Items.getItem(state, s.treatment.itemId);
        if (Js.T(item) && (item.reservedBy == s.id))
        {
            item.reservedBy = null;
        }
        s.treatment = null;
        s.goal = null;
        s.path = [];
        s.pathVersion = -1;
        s.note = note;
    }

    /// <summary>Satiety drains every tick, awake or asleep.</summary>
    public static void updateSatiety(SimState state, Survivor s)
    {
        if (Policies.satietyDrains(state) && Time.slowTick(state.tick))
        {
            s.satiety = JsMath.max(0, s.satiety - Food.SATIETY_DRAIN);
        }
    }

    /// <summary>Starving (satiety 0) costs health every tick; sleep heals, and so does being awake and fed, more slowly. Returns the cause if the survivor died this tick; the caller removes them (after the survivor loop, so the array isn't spliced mid-iteration).</summary>
    public static string? updateHealth(SimState state, Survivor s)
    {
        if (s.satiety == 0)
        {
            s.health = JsMath.max(0, s.health - Health.STARVE_DAMAGE);
        }
        else if (Seasons.isCold(state, s))
        {
        }
        else if (Js.T((s.health > 0) && Js.T(Js.T(s.sleep?.asleep))))
        {
            s.health = JsMath.min(Health.HEALTH_MAX, s.health + (Health.SLEEP_HEAL * (Medicine.inInfirmary(state, s) ? Medicine.INFIRMARY_HEAL_FACTOR : 1)));
        }
        else if (((s.health > 0) && !isHungry(s)) && ((state.tick % Health.AWAKE_HEAL_EVERY) == 0))
        {
            s.health = JsMath.min(Health.HEALTH_MAX, s.health + 1);
        }
        if (s.health > 0)
        {
            return null;
        }
        return (s.satiety == 0) ? "starvation" : (s.lastHurtBy ?? "injuries");
    }

    /// <summary>Death (or, with walkedAway, leaving for good: no body, no mourning).</summary>
    public static void killSurvivor(SimState state, Survivor s, string cause, bool walkedAway = false)
    {
        if ((state.control?.survivorId == s.id) && !Js.T(walkedAway))
        {
            SuccessionMod.beginSuccession(state, s, cause);
        }
        cancelMeal(state, s, cause);
        if (Js.T(Js.T(s.jobId) || Js.T(s.carrying)))
        {
            Jobs.releaseSurvivor(state, s, cause);
        }
        wake(state, s, cause);
        cancelTreatment(state, s, cause);
        Weapons.cancelArming(state, s, cause);
        Clothing.cancelDressing(state, s, cause);
        Books.stopReading(state, s, cause);
        Weapons.dropWeapon(state, s);
        Inventory.dropPack(state, s);
        Clothing.undress(state, s);
        if ((cause != "the infection") && !Js.T(walkedAway))
        {
            Corpses.leaveCorpse(state, s.pos, s.name);
        }
        foreach (var f in Js.Iter(FurnitureMod.ofKind(state, "bed")))
        {
            if (f.owner == s.id)
            {
                f.owner = null;
            }
        }
        var i = state.survivors.indexOf(s);
        if (i >= 0)
        {
            state.survivors.splice(i, 1);
        }
        if (Js.T(walkedAway))
        {
            return;
        }
        Events.logEvent(state, $"{Js.Str(s.name)} died of {Js.Str(cause)}");
        Mood.mournDeath(state, s);
    }

    /// <summary>Runs when the survivor is standing still. Returns true if sleep handled this tick (so the survivor doesn't also look for work).</summary>
    public static bool updateSleep(SimState state, Survivor s)
    {
        if (!Js.T(s.sleep))
        {
            if (!wantsSleep(state, s) || onGuardDuty(state, s))
            {
                return false;
            }
            startSleep(state, s);
            return true;
        }
        var sleep = s.sleep;
        if (Js.T(sleep.asleep))
        {
            return true;
        }
        var bed = Js.T(sleep.bedId) ? getBed(state, sleep.bedId) : null;
        if (!Js.T(bed))
        {
            sleep.bedId = null;
            sleep.asleep = true;
            s.note = "asleep on the floor";
            return true;
        }
        if (Space.samePoint(s.pos, bed))
        {
            sleep.asleep = true;
            s.note = $"asleep in bed at ({Js.Str(bed.x)}, {Js.Str(bed.y)})";
            return true;
        }
        var path = Pathfinding.findPathToAny(state.grid, s.pos, [bed]);
        if (Js.T(path) && (path.length > 0))
        {
            Survivors.walk(s, path, state.walkabilityVersion);
            return true;
        }
        bed.occupant = null;
        s.sleep = new Sleep { bedId = null, asleep = true };
        s.note = "no way to a bed, asleep on the floor";
        return true;
    }

    public static void startSleep(SimState state, Survivor s)
    {
        if (Js.T(s.jobId))
        {
            Jobs.releaseSurvivor(state, s, "too tired to work");
        }
        var bed = nearestFreeBed(state, s);
        if (!Js.T(bed))
        {
            s.sleep = new Sleep { bedId = null, asleep = true };
            s.note = "no free bed, asleep on the floor";
            return;
        }
        bed.occupant = s.id;
        if (((bed.owner == null) && !Medicine.isInfirmaryBed(state, bed)) && !FurnitureMod.ofKind(state, "bed").some((f) => f.owner == s.id))
        {
            bed.owner = s.id;
        }
        s.sleep = new Sleep { bedId = bed.id, asleep = false };
        s.note = $"going to bed at ({Js.Str(bed.x)}, {Js.Str(bed.y)})";
        if (Space.samePoint(s.pos, bed))
        {
            s.sleep.asleep = true;
            s.note = $"asleep in bed at ({Js.Str(bed.x)}, {Js.Str(bed.y)})";
            return;
        }
        var path = Pathfinding.findPathToAny(state.grid, s.pos, [bed]);
        if (Js.T(path) && (path.length > 0))
        {
            Survivors.walk(s, path, state.walkabilityVersion);
        }
    }

    /// <summary>Which bed: never someone else's. The hurt try infirmary beds first, everyone else saves them for the hurt; then your own bed; then guards take barracks beds and others leave them; then nearest.</summary>
    public static Furniture? nearestFreeBed(SimState state, Survivor s)
    {
        var hurt = Health.isHurt(s.health);
        var guard = Medicine.isGuard(s);
        double rank(Furniture f)
        {
            return (((Medicine.isInfirmaryBed(state, f) == hurt) ? 0 : 4) + ((f.owner == s.id) ? 0 : 2)) + ((Medicine.isBarracksBed(state, f) == guard) ? 0 : 1);
        }
        return FurnitureMod.ofKind(state, "bed").filter((f) => (f.occupant == null) && ((f.owner == null) || (f.owner == s.id))).sort((a, b) => ((rank(a) - rank(b)) is var __or0 && Js.T(__or0) ? __or0 : (Space.manhattan(s.pos, a) - Space.manhattan(s.pos, b)))).find((f) => Pathfinding.canReach(state.grid, state.walkabilityVersion, s.pos, [f]));
    }

    /// <summary>Drains or restores rest; wakes the survivor when full. Runs every tick, after movement and work.</summary>
    public static void updateRest(SimState state, Survivor s)
    {
        if (!Time.slowTick(state.tick))
        {
            return;
        }
        if (!Js.T(Js.T(s.sleep?.asleep)))
        {
            s.rest = JsMath.max(0, s.rest - Rest.REST_DRAIN);
            return;
        }
        var inBed = (s.sleep.bedId != null) && (FurnitureMod.furnitureAt(state, s.pos.x, s.pos.y)?.id == s.sleep.bedId);
        s.rest = JsMath.min(Rest.REST_MAX, s.rest + (Js.T(inBed) ? Rest.BED_REGEN : Rest.FLOOR_REGEN));
        if ((s.rest >= Rest.REST_MAX) && (!Health.isHurt(s.health) || isHungry(s)))
        {
            Mood.addThought(state, s, Js.T(s.sleep.bedId) ? "sleptInBed" : "sleptOnFloor");
            if (Js.T(s.sleep.bedId))
            {
                Mood.addThought(state, s, "wellRested");
            }
            Wellbeing.wakeComfort(state, s, s.sleep.bedId);
            wake(state, s, "woke up rested");
        }
    }

    /// <summary>Guards asleep in a barracks bed wake when a zombie comes within DANGER_RADIUS (others only when hit).</summary>
    public static void wakeLightSleepers(SimState state)
    {
        foreach (var s in Js.Iter(state.survivors))
        {
            if (((!Js.T(Js.T(s.sleep?.asleep)) || !Js.T(s.sleep.bedId)) || !Medicine.isGuard(s)) || Health.isCritical(s.health))
            {
                continue;
            }
            var bed = getBed(state, s.sleep.bedId);
            if ((Js.T(bed) && Medicine.isBarracksBed(state, bed)) && Zombies.zombieNear(state, s.pos))
            {
                wake(state, s, "woken for guard duty");
            }
        }
    }

    public static void wake(SimState state, Survivor s, string note)
    {
        if (!Js.T(s.sleep))
        {
            return;
        }
        var bed = Js.T(s.sleep.bedId) ? getBed(state, s.sleep.bedId) : null;
        if (Js.T(bed) && (bed.occupant == s.id))
        {
            bed.occupant = null;
        }
        s.sleep = null;
        s.note = note;
    }
